// Serves the branded Open Graph share image with a clean HTTP 200.
//
// Why this exists: Vercel's CDN adds HTTP Range support to static files, so a
// static image answers crawler requests (Facebook, WhatsApp) that send a
// "Range" header with "206 Partial Content". WhatsApp/Facebook reject 206
// responses for preview images, so the logo never renders. Serving the bytes
// from a function returns a plain 200 (Range is not honored), which the
// scrapers accept. The image is inlined as base64 so it is always bundled with
// the function regardless of file tracing. Raw card also at /og-image.jpg.
const IMG = Buffer.from(
  "",
  "base64"
);

module.exports = (req, res) => {
  res.statusCode = 200;
  res.setHeader("Content-Type", "image/jpeg");
  res.setHeader("Content-Length", String(IMG.length));
  res.setHeader("Accept-Ranges", "none");
  res.setHeader("Cache-Control", "public, max-age=86400, s-maxage=86400");
  res.end(IMG);
};
